INSERT /* SQL_ID: IdSchemeCodeMapper.insertIdSchemeStdInd */
       INTO dtmeta.tb_meta_idschmstdind
	 ( id_schm_cd
	 , id_schm_cd_nm
	 , id_schm_cd_eng_nm
	 , cd_size_div_mtcd
	 , lctg_extr_cd
	 , origin_extr_cd
	 , idfy_use_yn
	 , use_yn
	 , id_schm_cd_desc
	 , id_schm_cd_regr_id
	 , id_schm_cd_regr_nm
	 , id_schm_cd_reg_dt
	 , id_schm_cd_amdr_id
	 , id_schm_cd_amdr_nm
	 , id_schm_cd_amd_dt			
	 ) VALUES 
	 ( 
	   #{idSchmCd}			 			 
	 , #{idSchmCdNm}
	 , #{idSchmCdEngNm}
	 , #{cdSizeDivMtcd}
	 , #{lctgExtrCd}
	 , #{originExtrCd}
	 , #{idfyUseYn}
	 , #{useYn}
	 , #{idSchmCdDesc}
	 , #{idSchmCdRegrId}
	 , #{idSchmCdRegrNm}
	 , current_timestamp
	 , #{idSchmCdAmdrId}
	 , #{idSchmCdAmdrNm}
	 , current_timestamp			 
	 )

mapper.update:
		UPDATE /* SQL_ID: IdSchemeCodeMapper.updateIdSchemeStdInd */
               dtmeta.tb_meta_idschmstdind
		   SET id_schm_cd_nm          = #{idSchmCdNm}
             , id_schm_cd_eng_nm      = #{idSchmCdEngNm}
             , id_schm_cd_desc 		  = #{idSchmCdDesc}
             , use_yn                 = #{useYn}
             , id_schm_cd_amdr_id     = #{idSchmCdAmdrId}
             , id_schm_cd_amdr_nm     = #{idSchmCdAmdrNm}
             , id_schm_cd_amd_dt      = current_timestamp            
		 WHERE id_schm_cd 	    = #{idSchmCd}

